// Parse and validate notification request
const input = $input.first().json;
const body = input.body || input;

// Validate required fields
if (!body.recipient) {
  throw new Error('Missing required field: recipient');
}
if (!body.message && !body.template) {
  throw new Error('Missing required field: message or template');
}

// Default notification structure
const notification = {
  id: `notif_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  recipient: body.recipient,
  channels: body.channels || ['email'],
  priority: body.priority || 'normal',
  template: body.template || null,
  message: {
    subject: body.subject || body.message?.subject || 'Notification',
    body: body.message?.body || body.message || '',
    html: body.message?.html || null
  },
  metadata: body.metadata || {},
  createdAt: new Date().toISOString(),
  status: 'pending',
  deliveries: []
};

return [{ json: notification }];

// Load user preferences (in production, fetch from database)
// This simulates a preference lookup
const notification = $input.first().json;
const recipient = notification.recipient;

// Simulated user preferences (replace with database lookup)
const defaultPreferences = {
  channels: {
    email: { enabled: true, address: recipient.email || recipient },
    slack: { enabled: false, userId: null },
    sms: { enabled: false, phone: null },
    webhook: { enabled: false, url: null }
  },
  timezone: 'UTC',
  digestMode: false,
  quietHours: { enabled: false, start: '22:00', end: '08:00' }
};

// Merge with any provided preferences
const preferences = {
  ...defaultPreferences,
  ...(recipient.preferences || {})
};

return [{
  json: {
    notification,
    preferences,
    selectedChannels: notification.channels.filter(ch => 
      preferences.channels[ch]?.enabled !== false
    )
  }
}];

// Apply template if specified
const data = $input.first().json;
const notification = data.notification;

// Template library (in production, load from database)
const templates = {
  'welcome': {
    subject: 'Welcome to {{appName}}!',
    body: 'Hello {{name}}, welcome to {{appName}}. We\'re excited to have you!',
    html: '<h1>Welcome!</h1><p>Hello {{name}}, welcome to <strong>{{appName}}</strong>.</p>'
  },
  'alert': {
    subject: '[ALERT] {{alertType}}: {{summary}}',
    body: 'Alert: {{alertType}}\n\nDetails: {{details}}\n\nTime: {{timestamp}}',
    html: '<div style="background:#ff6b6b;color:white;padding:10px"><h2>{{alertType}}</h2><p>{{details}}</p></div>'
  },
  'digest': {
    subject: 'Your Daily Digest - {{date}}',
    body: 'Here\'s your summary for {{date}}:\n\n{{items}}',
    html: '<h2>Daily Digest</h2><p>{{date}}</p><ul>{{items}}</ul>'
  }
};

let message = notification.message;

if (notification.template && templates[notification.template]) {
  const template = templates[notification.template];
  const vars = notification.metadata || {};

  // Simple variable substitution
  const substitute = (str) => {
    if (!str) return str;
    return str.replace(/\{\{(\w+)\}\}/g, (match, key) => vars[key] || match);
  };

  message = {
    subject: substitute(template.subject),
    body: substitute(template.body),
    html: substitute(template.html)
  };
}

return [{
  json: {
    ...data,
    notification: {
      ...notification,
      message
    }
  }
}];

// Split into individual channel deliveries
const data = $input.first().json;
const channels = data.selectedChannels;

return channels.map(channel => ({
  json: {
    channel,
    notification: data.notification,
    preferences: data.preferences,
    deliveryId: `del_${Date.now()}_${channel}_${Math.random().toString(36).substr(2, 5)}`
  }
}));

// Track delivery status
const input = $input.first().json;
const channel = $('Split by Channel').first().json.channel;
const deliveryId = $('Split by Channel').first().json.deliveryId;
const notificationId = $('Split by Channel').first().json.notification.id;

// Determine if delivery was successful
const success = !input.error;

return [{
  json: {
    notificationId,
    deliveryId,
    channel,
    status: success ? 'delivered' : 'failed',
    error: input.error?.message || null,
    deliveredAt: success ? new Date().toISOString() : null
  }
}];

// Track Slack delivery
const input = $input.first().json;
const channel = 'slack';
const deliveryId = $('Split by Channel').first().json.deliveryId;
const notificationId = $('Split by Channel').first().json.notification.id;

const success = input.ok !== false && !input.error;

return [{
  json: {
    notificationId,
    deliveryId,
    channel,
    status: success ? 'delivered' : 'failed',
    error: input.error?.message || null,
    messageTs: input.ts || null,
    deliveredAt: success ? new Date().toISOString() : null
  }
}];

// Track SMS delivery
const input = $input.first().json;
const channel = 'sms';
const deliveryId = $('Split by Channel').first().json.deliveryId;
const notificationId = $('Split by Channel').first().json.notification.id;

const success = input.sid && !input.error;

return [{
  json: {
    notificationId,
    deliveryId,
    channel,
    status: success ? 'delivered' : 'failed',
    error: input.error?.message || null,
    messageSid: input.sid || null,
    deliveredAt: success ? new Date().toISOString() : null
  }
}];

// Track webhook delivery
const input = $input.first().json;
const channel = 'webhook';
const deliveryId = $('Split by Channel').first().json.deliveryId;
const notificationId = $('Split by Channel').first().json.notification.id;

const success = input.statusCode >= 200 && input.statusCode < 300;

return [{
  json: {
    notificationId,
    deliveryId,
    channel,
    status: success ? 'delivered' : 'failed',
    statusCode: input.statusCode || null,
    error: !success ? `HTTP ${input.statusCode}` : null,
    deliveredAt: success ? new Date().toISOString() : null
  }
}];

// Compile final delivery report
const deliveries = $input.all().map(i => i.json);
const notificationId = deliveries[0]?.notificationId;

const successful = deliveries.filter(d => d.status === 'delivered');
const failed = deliveries.filter(d => d.status === 'failed');

return [{
  json: {
    notificationId,
    status: failed.length === 0 ? 'delivered' : 
            successful.length === 0 ? 'failed' : 'partial',
    summary: {
      total: deliveries.length,
      delivered: successful.length,
      failed: failed.length
    },
    deliveries,
    completedAt: new Date().toISOString()
  }
}];
